    public static string Text(this Cause message) => message switch
    {
        Cause.NoSources => T.CauseNoSources,
        Cause.NoConnection => T.CauseNoConnection,
        Cause.AirsToday x => T.CauseAirsToday(x.Time),
        Cause.AirsTomorrow x => T.CauseAirsTomorrow(x.Time),
        Cause.AirsInDays x => T.CauseAirsInDays(x.Days, x.Time),
        Cause.AirsOnDate x => T.CauseAirsOnDate(x.Date, x.Time),
        Cause.NoPlayableStream => T.CauseNoPlayableStream,
        Cause.TitleNoMatch x => T.CauseTitleNoMatch(x.Detail),
        Cause.SourceGone x => T.CauseSourceGone(x.Source),
        Cause.ReleaseFailed x => T.CauseReleaseFailed(x.Detail),
        Cause.SourcesTimedOut => T.CauseSourcesTimedOut,
        Cause.NoSourceHasEpisode x => T.CauseNoSourceHasEpisode(x.Episode, x.Detail),
        Cause.SourceCannotDownload => T.CauseSourceCannotDownload,
        Cause.NoSourceCouldListShow => T.CauseNoSourceCouldListShow,
        Cause.SubtitlesMerged x => T.CauseSubtitlesMerged(x.Tracks),
        Cause.SubtitlesLeftApart x => T.CauseSubtitlesLeftApart(x.Reason),
        Cause.AlreadyInDownloads x => T.CauseAlreadyInDownloads(x.Count),
        Cause.ProxyNeedsAddress => T.CauseProxyNeedsAddress,
        Cause.ProxyAddressUnusable => T.CauseProxyAddressUnusable,
        Cause.ServerUnreachable => T.CauseServerUnreachable,
        Cause.Verbatim x => x.Text,
        _ => message.ToString() ?? "",
    };
